// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockNumberOffset) public {
        // Ensure msg.value is exactly 10 ether for the fallback to succeed
        vm.assume(amount == 10 ether);

        // Ensure block.number % 15 == 0 for the transfer to happen (not required for the invariant)
        // We only care about the state change of pastBlockTime

        // Record block.timestamp before the call
        uint256 timestampBefore = block.timestamp;

        // Make the fallback call
        (bool success, ) = address(c).call{value: amount}("");

        // If the call succeeded, check the invariant
        if (success) {
            assertTrue(c.pastBlockTime() > timestampBefore);
        }
    }
}

